package com.cryptoloan.notification.application;
import com.cryptoloan.notification.domain.model.Notification;import com.cryptoloan.notification.domain.port.out.NotificationPorts.*;import java.util.List;import org.slf4j.*;import org.springframework.stereotype.Service;
@Service public class NotificationService{private static final Logger log=LoggerFactory.getLogger(NotificationService.class);private final Repository repository;private final EmailSender emails;private final LivePublisher live;public NotificationService(Repository r,EmailSender e,LivePublisher l){repository=r;emails=e;live=l;}public Notification notify(String recipient,String type,String subject,String message,Long loanId){Notification n=repository.save(Notification.pending(recipient,type,subject,message,loanId));try{emails.send(recipient,subject,message);n=repository.save(n.sent());}catch(RuntimeException e){log.error("Échec de l'e-mail {} pour {}",type,recipient,e);n=repository.save(n.failed(e.getMessage()==null?"Erreur SMTP":e.getMessage().substring(0,Math.min(250,e.getMessage().length()))));}live.publish(n);return n;}public List<Notification>mine(String email){return repository.findForRecipient(email);}}

